import styled from "styled-components";
import HeroPhoto from "@/assets/Gallery_Photo_4.jpg";
import { invitation } from "@/data/invitation";
import { useDaysUntilCeremony } from "@/hooks/useDaysUntilCeremony";
import { formatCeremonyDateTime, toDateTimeAttribute } from "@/lib/ceremony";

/**
 * 첫 화면. 신랑·신부 이름과 예식 일시를 알린다.
 *
 * 예식 일시 문자열은 데이터의 ISO 시각에서 파생된다. 요일을 사람이 적지
 * 않으므로 날짜와 요일이 어긋날 수 없다.
 */
export function Hero() {
  const { couple, ceremony, venue } = invitation;
  const daysLeft = useDaysUntilCeremony(ceremony.startsAt);

  return (
    <Header>
      <Backdrop
        src={HeroPhoto}
        alt="따뜻한 실내에서 웨딩 촬영을 한 신랑과 신부"
        width={1400}
        height={2100}
        fetchPriority="high"
      />
      <Shade aria-hidden="true" />

      <Copy>
        <Top>
          <Eyebrow>WEDDING INVITATION</Eyebrow>
          <Names>
            {couple.groom.name} <Ampersand>&amp;</Ampersand> {couple.bride.name}
          </Names>
        </Top>

        <Bottom>
          <Schedule>
            <time dateTime={toDateTimeAttribute(ceremony.startsAt)}>
              {formatCeremonyDateTime(ceremony.startsAt)}
            </time>
            <br />
            {venue.name}
          </Schedule>
          <Countdown>
            {daysLeft !== null && daysLeft > 0
              ? `예식까지 ${daysLeft}일 남았습니다`
              : null}
          </Countdown>
        </Bottom>
      </Copy>
    </Header>
  );
}

const Header = styled.header`
  position: relative;
  width: 100%;
  max-width: ${({ theme }) => theme.layout.maxWidth};
  min-height: min(780px, 100svh);
  margin: 0 auto;
  overflow: hidden;
  background: #b8a18f;
  text-align: center;
  animation: fade-in ${({ theme }) => theme.motion.duration.slow} ease-out both;

  @keyframes fade-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
`;

const Backdrop = styled.img`
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 42%;
`;

const Shade = styled.div`
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(54, 38, 29, 0.42) 0%, transparent 38%),
    linear-gradient(0deg, rgba(43, 29, 22, 0.72) 0%, transparent 48%);
`;

const Copy = styled.div`
  position: relative;
  z-index: 1;
  display: flex;
  min-height: min(780px, 100svh);
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(44px, 10svh, 76px) 24px 36px;
  color: #fff;
`;

const Top = styled.div``;

const Bottom = styled.div``;

const Eyebrow = styled.p`
  margin-bottom: ${({ theme }) => theme.space[4]};
  color: rgba(255, 255, 255, 0.84);
  font-size: ${({ theme }) => theme.fontSize.xs};
  letter-spacing: 0.22em;
`;

const Names = styled.h1`
  margin-bottom: ${({ theme }) => theme.space[4]};
  color: #fff;
  font-size: clamp(1.75rem, 7vw, 2.25rem);
  font-weight: 500;
  letter-spacing: 0.08em;
  text-shadow: 0 1px 18px rgba(0, 0, 0, 0.22);
`;

const Ampersand = styled.span`
  margin: 0 0.2em;
  font-size: 0.65em;
  font-style: italic;
  opacity: 0.82;
`;

const Schedule = styled.p`
  margin-bottom: ${({ theme }) => theme.space[4]};
  color: rgba(255, 255, 255, 0.92);
  font-size: ${({ theme }) => theme.fontSize.sm};
  letter-spacing: 0.03em;
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.35);
`;

const Countdown = styled.p`
  /* 비어 있을 때도 한 줄 높이를 유지해 내용이 채워져도 레이아웃이 움직이지 않는다. */
  min-height: 1.75em;
  margin-bottom: ${({ theme }) => theme.space[6]};
  color: rgba(255, 255, 255, 0.78);
  font-size: ${({ theme }) => theme.fontSize.xs};
  letter-spacing: 0.08em;
`;
